insert into public.servicos (id, empresa, dados) values ('seo-busca-organica-46008-2', 'orb', $json${"id":"seo-busca-organica-46008-2","versao":1,"empresa":"orb","nome":"Planejamento para Busca Orgânica – SEO · HUB SEBRAE","nomeCurto":"SEO","fichaTecnica":"Planejamento para Busca Orgânica – SEO","codigoFichaTecnica":"46008-2","prestadoraVinculada":"","area":"Desenvolvimento tecnológico","descricao":"Planejamento e otimização da busca orgânica do site: estudo de posicionamento e palavras-chave, SEO on-page e monitoramento da indexação e do ranqueamento, em três etapas.","credenciado":true,"areaAtuacao":"Busca orgânica (SEO)","preDiagnostico":["Sua empresa tem praticado o marketing de conteúdo?","Sua empresa tem um site, blog, e-commerce?","Há propagação em redes sociais com criação de fluxo e engajamento para o seu projeto web?","Como você realiza a inserção de matérias e notícias no seu site?","Você utiliza algum estudo de palavras-chaves?","Seu site foi desenvolvido utilizando palavras-chaves?","Você monitora o ranqueamento do seu site em motores de busca (Google ou Bing)?","Você possui o Google Analytics no seu site?","Você tem monitorado o crescimento de acessos do seu site?","Tem utilizado algum indicador de performance (K.P.I) para medir o tráfego do seu site?","Em que setor(es) a empresa melhor se enquadra?","Em que segmento(s) a empresa melhor se enquadra?"],"etapas":[{"ordem":1,"nome":"PLANEJAMENTO TÉCNICO","descricao":"Elaborar o relatório de pesquisa e estudo de posicionamento (benchmarking e oportunidades), definir as melhores palavras-chave a serem otimizadas no site e desenvolver a pauta de cronograma de postagens, se houver SEO off-page.","horasPrevistas":18,"duracaoReferenciaDias":3,"atividades":[["1","Elaborar relatório de pesquisa e estudo de posicionamento (lista de benchmarking e oportunidades)"],["2","Definir as melhores palavras-chave a serem otimizadas no site"],["3","Desenvolver a pauta de cronograma de postagens (se houver SEO off-page)"]],"entregaveis":["Relatório de análise competitiva dos concorrentes e do posicionamento do site","Relatório de palavras-chaves"],"instrumentos":[]},{"ordem":2,"nome":"SEO ON-PAGE","descricao":"Revisar as marcações do código do site, definir títulos e descrições das páginas, adequar imagens e servidor ao carregamento, realizar link building e definir o formato dos guest posts.","horasPrevistas":25,"duracaoReferenciaDias":4,"atividades":[["1","Revisar todas as marcações do código do site (SEO on-page)"],["2","Definir os títulos e descrições de todas as páginas"],["3","Modificar o formato das imagens (compactar, atribuir marcações, inserir infográficos, adicionar vídeos)"],["4","Configurar o servidor para um melhor tempo de resposta no carregamento"],["5","Acompanhar a troca do servidor, caso seja necessário"],["6","Realizar link building para aumentar a relevância do site"],["7","Definir o formato para utilização dos guest posts"]],"entregaveis":["Estratégias de conteúdo para melhorar a performance do site","Posts publicados para SEO off-page"],"instrumentos":[]},{"ordem":3,"nome":"MONITORAMENTO","descricao":"Avaliar a indexação do site, revisar o planejamento e criar a estratégia de monitoramento dos próximos dois meses, com orientação sobre o acompanhamento de rankings e as ferramentas técnicas de análise e performance.","horasPrevistas":12,"duracaoReferenciaDias":2,"atividades":[["1","Avaliar o processo de indexação do site"],["2","Revisar o planejamento para os próximos 02 (dois) meses"],["3","Criar estratégia para monitoramento dos próximos 02 (dois) meses"],["4","Orientar a respeito do monitoramento de rankings no Google"],["5","Orientar a respeito de ferramentas técnicas para análise e performance do site"]],"entregaveis":["Relatório para análise de performance de indicadores (K.P.I)"],"instrumentos":[]}]}$json$::jsonb) on conflict (id) do nothing;
insert into public.servicos (id, empresa, dados) values ('links-patrocinados-46005-6', 'orb', $json${"id":"links-patrocinados-46005-6","versao":1,"empresa":"orb","nome":"Planejamento para Presença Digital e Links Patrocinados · HUB SEBRAE","nomeCurto":"Links Patrocinados","fichaTecnica":"Planejamento para Presença Digital e Links Patrocinados","codigoFichaTecnica":"46005-6","prestadoraVinculada":"","area":"Desenvolvimento tecnológico","descricao":"Planejamento da atuação da empresa em ambiente digital: alinhamento, diagnóstico interno e externo, projeto detalhado de planejamento digital e, quando contratada, execução das campanhas de links patrocinados (tráfego pago).","credenciado":true,"areaAtuacao":"Presença digital e links patrocinados (tráfego pago)","preDiagnostico":["A empresa deve ter seus objetivos e mercados desejados claramente definidos.","A empresa deve designar um responsável para fornecer os requisitos e demais orientações para a executora.","(Caso haja campanha) A empresa tem praticado o marketing de conteúdo?","(Caso haja campanha) A empresa monitora com frequência o crescimento de acesso do seu site?","(Caso haja campanha) A empresa já dispõe de uma Landing Page para captação de leads?","(Caso haja campanha) Criar campanha segmentadas por dispositivos é interessante para o seu negócio?","(Caso haja campanha) O cliente já fez um estudo de palavras chaves?","(Caso haja campanha) O cliente já definiu quanto quer investir em links patrocinados?","(Caso haja campanha) O cliente deseja contemplar nesta consultoria o Google Adwords?","(Caso haja campanha) O cliente deseja contemplar nesta consultoria o Facebook Ads?","(Caso haja campanha) O cliente deseja contemplar nesta consultoria o Instagram Ads?"],"etapas":[{"ordem":1,"nome":"ALINHAMENTO","descricao":"Reunião de alinhamento sobre a condução do trabalho, tratando das características dos produtos/serviços e do mercado alvo, dos recursos e da qualificação das pessoas envolvidas e do planejamento dos trabalhos.","horasPrevistas":6,"duracaoReferenciaDias":1,"atividades":[["1","Realizar reunião de alinhamento sobre a condução do trabalho"],["1.1","Tratar das características dos produtos/serviços e do mercado alvo"],["1.2","Tratar dos recursos e da qualificação das pessoas envolvidas"],["1.3","Tratar do planejamento dos trabalhos"]],"entregaveis":["Ata da reunião","Cronograma de execução"],"instrumentos":[]},{"ordem":2,"nome":"DIAGNÓSTICO","descricao":"Diagnóstico da organização e do mercado alvo, incluindo, quando aplicáveis, os diagnósticos interno e externo, o alinhamento com o planejamento estratégico, o levantamento das necessidades do negócio e da presença dos clientes no ecossistema digital.","horasPrevistas":22,"duracaoReferenciaDias":3,"atividades":[["1","Diagnóstico interno: estratégias e ações de marketing digital da empresa e suas repercussões, pontos de melhoria, uso de recursos, SEO, métricas e retorno sobre o investimento"],["2","Diagnóstico externo: análise do mercado, público alvo, personas, segmento de atuação, concorrência, reputação da marca, oportunidades e ameaças"],["2.1","Quando houver execução de campanha: como minimizar o Custo por Clique (CPC) e aumentar a Taxa de Cliques (CTR), canais web a serem utilizados e conteúdos baseados nos canais escolhidos"],["3","Alinhar com o planejamento estratégico da empresa: objetivos, metas e indicadores de performance das ações digitais"],["4","Levantar as necessidades do negócio, a partir da imersão nos objetivos estratégicos do cliente"],["5","Levantar a presença dos clientes no ecossistema digital da empresa, como insumo para o planejamento"],["6","Elaborar o relatório"]],"entregaveis":["Relatório do Diagnóstico Inicial (obrigatório)","Planilha com a estrutura da campanha organizada por Grupos, Anúncios, Plataforma e Palavras-Chaves (opcional, quando houver campanha)"],"instrumentos":[]},{"ordem":3,"nome":"PROJETO PARA PLANEJAMENTO DIGITAL","descricao":"Projeto detalhado, com planejamento dos serviços e das ações a serem implementados para tecnologias digitais: plano de ação, mídias sociais, busca orgânica, diretrizes de governança, links patrocinados e métricas.","horasPrevistas":25,"duracaoReferenciaDias":4,"atividades":[["1","Elaborar o plano de ação: canais, personas, mensagens, investimentos, cronograma de implantação, monitoramento e mensuração de resultados"],["2","Identificar padrões, recursos, funcionalidades e tendências de mercado no projeto para o posicionamento digital"],["3","Planejar a atuação em mídias sociais"],["4","Planejar a busca orgânica: análise e relatório"],["5","Definir diretrizes de governança para manutenção da estratégia de posicionamento na internet"],["6","Planejar a atuação com links patrocinados e outras estratégias de mídia paga em ambiente digital"],["6.1","Quando houver campanha: definir os objetivos da campanha com base nos estudos realizados"],["6.2","Quando houver campanha: criar as contas nas plataformas de links patrocinados (localidade, sexo, faixa etária, idade etc.)"],["6.3","Quando houver campanha: definir as palavras-chave e o local de veiculação (Display e/ou Pesquisa)"],["6.4","Quando houver campanha: definir o investimento com base no aumento do ROI e na diminuição do custo por aquisição (CPA)"],["6.5","Quando houver campanha: criar as campanhas e otimizar o recurso para aumento do ROI"],["6.6","Quando houver campanha: definir o monitoramento (revisão das campanhas, otimização dos anúncios, conversões, CPC, CTR, segmentação do público e melhorias para as próximas campanhas)"],["7","Planejar a implantação de métricas (Analytics, monitoramento da estratégia digital etc.)"],["8","Desenvolver melhorias ou customizações de ambientes tecnológicos na web conforme as necessidades apontadas no planejamento"]],"entregaveis":["Projeto Detalhado","Métricas a serem implementadas (Analytics, monitoramento da estratégia digital etc.)","Documento com possíveis melhorias para as próximas campanhas, validado pela empresa demandante (opcional)"],"instrumentos":[]},{"ordem":4,"nome":"EXECUÇÃO DAS CAMPANHAS (OPCIONAL)","descricao":"Execução das campanhas digitais conforme o planejamento aprovado na etapa anterior. Só é realizada quando contratada com escopo estendido para execução.","horasPrevistas":14,"duracaoReferenciaDias":2,"atividades":[["1","Criar as campanhas nas plataformas escolhidas"],["2","Publicar e ativar os anúncios"],["3","Acompanhar a veiculação conforme o cronograma"],["4","Realizar otimizações contínuas com foco em ROI e desempenho"],["5","Elaborar relatórios com análise de métricas de desempenho (CPC, CTR, conversões etc.)"],["6","Ajustar as campanhas conforme o comportamento do público-alvo"],["7","Realizar reuniões de acompanhamento com a empresa demandante"]],"entregaveis":["Campanhas ativas nas plataformas contratadas","Relatórios de desempenho com evidências","Registro das otimizações realizadas","Ata de reunião de acompanhamento (opcional)"],"instrumentos":[]}]}$json$::jsonb) on conflict (id) do nothing;
